// Bklit UI theme, ported to Kinetograph frames. Chart design after Bklit UI (MIT), https://bklit.com.
//
// What lives here: the Bklit colour tokens (the `--chart-*` palettes and the neutral chart variables, light and
// dark, converted from oklch to hex), the numbers the Bklit components animate with (reveal easing, spring values,
// stagger delays), a few path helpers, and the camera director every Bklit chart here shares. Nothing keeps state.

import { z } from 'zod';
import { Easing } from 'remotion';
import { clamp01, lerp } from './lib.js';

// ---------------------------------------------------------------------------------------------------------------
// oklch -> hex

/** Convert a CSS `oklch(L C H)` string (L 0..1, C, H degrees) to `#rrggbb`. */
export function oklchHex(css: string): string {
  const m = css.match(/oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)/);
  if (!m) throw new Error('bad oklch: ' + css);
  const L = +m[1];
  const C = +m[2];
  const h = (+m[3] * Math.PI) / 180;
  const a = C * Math.cos(h);
  const b = C * Math.sin(h);
  const l_ = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m_ = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s_ = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const lin = [
    4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
    -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
    -0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_,
  ];
  const enc = (v: number) => {
    const c = Math.max(0, Math.min(1, v));
    const g = c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055;
    return Math.round(Math.max(0, Math.min(1, g)) * 255);
  };
  return '#' + lin.map((v) => enc(v).toString(16).padStart(2, '0')).join('');
}

const toRgb = (hex: string) => {
  const n = parseInt(hex.slice(1, 7), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};
/** Mix two hex colours: t=0 gives a, t=1 gives b. The opaque stand-in for "colour at some opacity over a ground". */
export function mix(a: string, b: string, t: number): string {
  const A = toRgb(a);
  const B = toRgb(b);
  return '#' + A.map((v, i) => Math.round(lerp(v, B[i], clamp01(t))).toString(16).padStart(2, '0')).join('');
}

// ---------------------------------------------------------------------------------------------------------------
// Palettes: bklit packages/studio/src/lib/chart-palettes.ts (values verbatim, oklch)

type Pal = { light: string[]; dark: string[] };
const TREND = {
  light: ['oklch(0.696 0.17 162.48)', 'oklch(0.637 0.237 25.331)'],
  dark: ['oklch(0.765 0.177 163.223)', 'oklch(0.704 0.191 22.216)'],
};
const RAW: Record<string, Pal> = {
  primary: {
    light: ['oklch(0.585 0.233 277.117)', 'oklch(0.852 0.199 91.936)', 'oklch(0.667 0.295 322.15)', 'oklch(0.56 0.021 213.5)', 'oklch(0 0 0)'],
    dark: ['oklch(0.585 0.233 277.117)', 'oklch(0.852 0.199 91.936)', 'oklch(0.667 0.295 322.15)', 'oklch(0.56 0.021 213.5)', 'oklch(1 0 0)'],
  },
  monochrome: {
    light: ['oklch(0.268 0.007 34.298)', 'oklch(0.444 0.011 73.639)', 'oklch(0.709 0.01 56.259)', 'oklch(0.869 0.005 56.366)', 'oklch(0.923 0.003 48.717)'],
    dark: ['oklch(0.967 0.001 286.375)', 'oklch(0.871 0.006 286.286)', 'oklch(0.705 0.015 286.067)', 'oklch(0.552 0.016 285.938)', 'oklch(0.442 0.017 285.786)'],
  },
  ocean: {
    light: ['oklch(0.546 0.245 262.881)', 'oklch(0.715 0.143 215.221)', 'oklch(0.777 0.152 181.912)', 'oklch(0.673 0.182 276.935)', 'oklch(0.828 0.111 230.318)'],
    dark: ['oklch(0.623 0.214 259.815)', 'oklch(0.789 0.154 211.53)', 'oklch(0.855 0.138 181.071)', 'oklch(0.785 0.115 274.713)', 'oklch(0.901 0.058 230.902)'],
  },
  sunset: {
    light: ['oklch(0.705 0.213 47.604)', 'oklch(0.645 0.246 16.439)', 'oklch(0.828 0.189 84.429)', 'oklch(0.627 0.265 303.9)', 'oklch(0.823 0.12 346.018)'],
    dark: ['oklch(0.75 0.183 55.934)', 'oklch(0.712 0.194 13.428)', 'oklch(0.879 0.169 91.605)', 'oklch(0.714 0.203 305.504)', 'oklch(0.899 0.061 343.231)'],
  },
  grove: {
    light: ['oklch(0.596 0.145 163.225)', 'oklch(0.768 0.233 130.85)', 'oklch(0.511 0.096 186.391)', 'oklch(0.769 0.188 70.08)', 'oklch(0.709 0.01 56.259)'],
    dark: ['oklch(0.765 0.177 163.223)', 'oklch(0.841 0.238 128.85)', 'oklch(0.6 0.118 184.704)', 'oklch(0.828 0.189 84.429)', 'oklch(0.709 0.01 56.259)'],
  },
  vivid: {
    light: ['oklch(0.606 0.25 292.717)', 'oklch(0.656 0.241 354.308)', 'oklch(0.715 0.143 215.221)', 'oklch(0.768 0.233 130.85)', 'oklch(0.705 0.213 47.604)'],
    dark: ['oklch(0.702 0.183 293.541)', 'oklch(0.718 0.202 349.761)', 'oklch(0.865 0.127 207.078)', 'oklch(0.897 0.196 126.665)', 'oklch(0.75 0.183 55.934)'],
  },
};
export const PALETTE_IDS = ['primary', 'monochrome', 'ocean', 'sunset', 'grove', 'vivid'] as const;

export const bkPaletteSchema = z.enum(PALETTE_IDS).describe('Bklit chart palette: primary (indigo, yellow, fuchsia, mist, black), monochrome, ocean, sunset, grove or vivid.');
export const bkModeSchema = z.enum(['light', 'dark']).describe('Colour theme: light or dark (Bklit tokens for each).');

export interface BkTokens {
  dark: boolean;
  /** --chart-background */
  bg: string;
  /** --foreground */
  fg: string;
  /** --muted-foreground */
  mutedFg: string;
  /** --border (the Ring track, tooltip border) */
  border: string;
  /** --chart-tooltip-background */
  popover: string;
  popoverFg: string;
  /** --chart-grid */
  grid: string;
  /** --chart-label: axis text */
  label: string;
  /** --chart-crosshair */
  crosshair: string;
  /** --chart-1 .. --chart-5 */
  series: string[];
  /** --chart-positive / --chart-negative */
  positive: string;
  negative: string;
  /** --chart-scale-01 .. 05 */
  scale: string[];
  /** The date-ticker pill (zinc-900 on white, zinc-100 on dark). */
  pill: string;
  pillFg: string;
  /** --legend-track */
  track: string;
}

export function tokens(mode: 'light' | 'dark', palette: string): BkTokens {
  const dark = mode === 'dark';
  const pal = RAW[palette] ?? RAW.primary;
  const series = pal[mode].map(oklchHex);
  const [positive, negative] = TREND[mode].map(oklchHex);
  const bg = oklchHex(dark ? 'oklch(0.145 0 0)' : 'oklch(1 0 0)');
  const fg = oklchHex(dark ? 'oklch(0.985 0 0)' : 'oklch(0.145 0 0)');
  // --chart-scale-0N: color-mix(in oklab, chart-1 N%, scale-mix); 01 is the neutral
  const mixTo = oklchHex(dark ? 'oklch(0.25 0 0)' : 'oklch(1 0 0)');
  const scale = [
    oklchHex(dark ? 'oklch(0.3 0 0)' : 'oklch(0.922 0 0)'),
    mix(mixTo, series[0], 0.35),
    mix(mixTo, series[0], 0.55),
    mix(mixTo, series[0], 0.78),
    series[0],
  ];
  return {
    dark, bg, fg, positive, negative, series, scale,
    mutedFg: oklchHex(dark ? 'oklch(0.708 0 0)' : 'oklch(0.556 0 0)'),
    border: dark ? mix(bg, '#ffffff', 0.1) : oklchHex('oklch(0.922 0 0)'),
    popover: oklchHex(dark ? 'oklch(0.205 0 0)' : 'oklch(1 0 0)'),
    popoverFg: fg,
    // dark grid is oklch(0.6 0.0124 243.77 / 0.25) over the background
    grid: dark ? mix(bg, oklchHex('oklch(0.6 0.0124 243.77)'), 0.25) : oklchHex('oklch(0.9 0 0)'),
    label: oklchHex(dark ? 'oklch(0.75 0.01 260)' : 'oklch(0.45 0.01 260)'),
    crosshair: oklchHex(dark ? 'oklch(0.72 0.0158 281.84)' : 'oklch(0.4 0.1828 274.34)'),
    pill: dark ? '#f4f4f5' : '#18181b',
    pillFg: dark ? '#18181b' : '#ffffff',
    track: oklchHex(dark ? 'oklch(0.274 0.006 286.033)' : 'oklch(0.92 0.004 286.32)'),
  };
}

// ---------------------------------------------------------------------------------------------------------------
// Bklit motion numbers

/** DEFAULT_ANIMATION_EASING: the clip reveal of the cartesian charts. */
export const easeBk = Easing.bezier(0.85, 0, 0.15, 1);
/** A softer in-out for a reveal the camera has to ride (the same family, less abrupt). */
export const easeRide = Easing.bezier(0.6, 0, 0.3, 1);
/** Grid ring and spoke enter stagger (seconds), from animation.ts. */
export const GRID_RING_STAGGER_S = 0.08;
export const GRID_SPOKE_STAGGER_S = 0.05;

/** Scale factor from Bklit's CSS pixels (a ~700 px wide card) to a 1920 px frame. */
export const PX = 2;

// ---------------------------------------------------------------------------------------------------------------
// Camera direction

/** One move of the camera. s is 0..1 progress of the move. The result w is where the camera is between the "from"
 *  and "to" poses: an eased 0..1 with a small pull back before it goes (anticipation) and a small overshoot at the
 *  end that settles back. `ant` and `over` are fractions of the move. */
export function moveCurve(s: number, ant = 0.035, over = 0.06): number {
  const t = clamp01(s);
  const base = Easing.bezier(0.55, 0, 0.2, 1)(t);
  const pull = -ant * Math.sin(Math.PI * clamp01(t / 0.2));
  const settle = over * Math.sin(Math.PI * clamp01((t - 0.72) / 0.28));
  return base + pull + settle;
}

/** Shutter (in frames) for the motion blur of a camera that went from pose a to pose b in one frame, poses as
 *  [x, y, zoom] in world pixels. Pixels of screen travel per frame decide it; a slow drift gets none. */
export function shutterFor(a: [number, number, number], b: [number, number, number]): number {
  const zm = (a[2] + b[2]) / 2;
  const dx = (b[0] - a[0]) * zm;
  const dy = (b[1] - a[1]) * zm;
  const dz = Math.abs(b[2] / a[2] - 1) * 900;
  const speed = Math.hypot(dx, dy) + dz;
  if (speed < 9) return 0;
  return Math.min(0.85, speed / 70);
}

/** A blur radius that is zero where the subject is in focus and rises with `depth` (0..1) to `max` px. Under 1 px
 *  the engine drops a blur, so return 0 there. */
export const soft = (depth: number, max = 5) => {
  const r = clamp01(depth) * max;
  return r < 1 ? 0 : r;
};

// ---------------------------------------------------------------------------------------------------------------
// Geometry

/** Angles in radians, clockwise from 12 o'clock (d3's arc convention). Point at radius r. */
export const polar = (cx: number, cy: number, r: number, a: number): [number, number] => [cx + Math.sin(a) * r, cy - Math.cos(a) * r];

const f2 = (v: number) => v.toFixed(2);

/** A filled annular sector from a0 to a1 (radians, clockwise from 12), outer radius r1, inner r0, with rounded
 *  corners of radius `corner` (a quadratic round-off, as d3's cornerRadius draws). r0 = 0 gives a pie slice. */
export function arcPath(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number, corner = 0): string {
  if (a1 - a0 < 0.0005) return '';
  const full = a1 - a0 >= Math.PI * 2 - 0.0005;
  if (full) {
    const o = `M${f2(cx)} ${f2(cy - r1)}A${r1} ${r1} 0 1 1 ${f2(cx)} ${f2(cy + r1)}A${r1} ${r1} 0 1 1 ${f2(cx)} ${f2(cy - r1)}Z`;
    if (r0 <= 0) return o;
    return o + `M${f2(cx)} ${f2(cy - r0)}A${r0} ${r0} 0 1 0 ${f2(cx)} ${f2(cy + r0)}A${r0} ${r0} 0 1 0 ${f2(cx)} ${f2(cy - r0)}Z`;
  }
  const cr = Math.max(0, Math.min(corner, (r1 - r0) / 2 - 0.01, ((a1 - a0) * Math.max(r0, 1)) / 2 - 0.01));
  const da1 = cr / r1;
  const da0 = r0 > 0 ? cr / r0 : 0;
  const large = (aa: number, bb: number) => (bb - aa > Math.PI ? 1 : 0);
  if (cr <= 0.01) {
    const [ox0, oy0] = polar(cx, cy, r1, a0);
    const [ox1, oy1] = polar(cx, cy, r1, a1);
    if (r0 <= 0) return `M${f2(cx)} ${f2(cy)}L${f2(ox0)} ${f2(oy0)}A${r1} ${r1} 0 ${large(a0, a1)} 1 ${f2(ox1)} ${f2(oy1)}Z`;
    const [ix1, iy1] = polar(cx, cy, r0, a1);
    const [ix0, iy0] = polar(cx, cy, r0, a0);
    return `M${f2(ox0)} ${f2(oy0)}A${r1} ${r1} 0 ${large(a0, a1)} 1 ${f2(ox1)} ${f2(oy1)}L${f2(ix1)} ${f2(iy1)}A${r0} ${r0} 0 ${large(a0, a1)} 0 ${f2(ix0)} ${f2(iy0)}Z`;
  }
  // outer arc between the rounded corners
  const P = (r: number, a: number) => polar(cx, cy, r, a).map(f2).join(' ');
  let d = `M${P(r1 - cr, a0)}`;
  d += `Q${P(r1, a0)} ${P(r1, a0 + da1)}`;
  d += `A${r1} ${r1} 0 ${large(a0 + da1, a1 - da1)} 1 ${P(r1, a1 - da1)}`;
  d += `Q${P(r1, a1)} ${P(r1 - cr, a1)}`;
  if (r0 <= 0) {
    d += `L${f2(cx)} ${f2(cy)}Z`;
    return d;
  }
  d += `L${P(r0 + cr, a1)}`;
  d += `Q${P(r0, a1)} ${P(r0, a1 - da0)}`;
  d += `A${r0} ${r0} 0 ${large(a0 + da0, a1 - da0)} 0 ${P(r0, a0 + da0)}`;
  d += `Q${P(r0, a0)} ${P(r0 + cr, a0)}Z`;
  return d;
}

/** Closed polygon through points. */
export const poly = (pts: [number, number][]) => pts.map(([x, y], i) => `${i ? 'L' : 'M'}${f2(x)} ${f2(y)}`).join('') + 'Z';

/** Rounded top corners only (a bar, a candle body), as a path. */
export const roundRectPath = (x: number, y: number, w: number, h: number, r: number) => {
  const rr = Math.min(r, w / 2, h / 2);
  return `M${f2(x + rr)} ${f2(y)}H${f2(x + w - rr)}Q${f2(x + w)} ${f2(y)} ${f2(x + w)} ${f2(y + rr)}V${f2(y + h - rr)}Q${f2(x + w)} ${f2(y + h)} ${f2(x + w - rr)} ${f2(y + h)}H${f2(x + rr)}Q${f2(x)} ${f2(y + h)} ${f2(x)} ${f2(y + h - rr)}V${f2(y + rr)}Q${f2(x)} ${f2(y)} ${f2(x + rr)} ${f2(y)}Z`;
};

/** Width of a sans (Geist) string, close enough for centring a pill: 0.56 em a character. */
export const sansWidth = (text: string, size: number) => text.length * size * 0.56;

/** Thousand-grouped integer. */
export const group = (v: number) => Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');

/** A cubic Bezier through horizontal handles (the sankey link / funnel curve): point at t. */
export function hCubic(x0: number, y0: number, x1: number, y1: number, t: number): [number, number] {
  const cx = (x0 + x1) / 2;
  const u = 1 - t;
  return [u * u * u * x0 + 3 * u * u * t * cx + 3 * u * t * t * cx + t * t * t * x1, u * u * u * y0 + 3 * u * u * t * y0 + 3 * u * t * t * y1 + t * t * t * y1];
}

/** Ease out with a small overshoot (a pop). 0..1 in, about 0..1.08..1 out. */
export const backOut = (t: number, c1 = 1.70158) => {
  const x = clamp01(t) - 1;
  return 1 + (c1 + 1) * x * x * x + c1 * x * x;
};

/** Linear sample of a function over [a, b] averaged at n points: a smoothed look-ahead for a camera that rides a line. */
export function avg(fn: (x: number) => number, a: number, b: number, n = 9): number {
  let s = 0;
  for (let i = 0; i < n; i++) s += fn(a + ((b - a) * i) / (n - 1));
  return s / n;
}

// Pieces every Bklit chart here draws: the tooltip panel, the date pill, a blur wrapper for rack focus, the heading.
// Chart design after Bklit UI (MIT). Sizes are Bklit's CSS pixels times PX (2).

import React from 'react';
import { Ellipse, Layer, Rect, Text, blur, dropShadow } from '@kinetographdev/core';
import type { Fonts } from './lib.js';
import { PX, mix, sansWidth, type BkTokens } from './bklit.js';

export interface TipRow {
  color: string;
  label: string;
  value: string;
}

/** Bklit's tooltip panel: rounded-xl, 1 px border, a header row split off by a border, then rows of a 8 px dot, a
 *  muted label and a medium value. (x, y) is the panel's top-left; scale and opacity pivot on its middle. */
export const BkTooltip: React.FC<{
  id: string;
  x: number;
  y: number;
  title?: string;
  rows: TipRow[];
  tk: BkTokens;
  fonts: Fonts;
  width?: number;
  opacity?: number;
  scale?: number;
  /** Local point the scale pivots on; default the middle. */
  pivot?: [number, number];
}> = ({ id, x, y, title, rows, tk, fonts, width = 160 * PX, opacity = 1, scale = 1, pivot }) => {
  const headH = title ? 40 * PX : 0;
  const bodyH = (24 + rows.length * 20 + Math.max(0, rows.length - 1) * 8) * PX;
  const h = headH + bodyH;
  const [px, py] = pivot ?? [width / 2, h / 2];
  return (
    <Layer id={id} x={x + px} y={y + py} anchorX={px} anchorY={py} opacity={opacity} scale={scale}
      effects={[dropShadow({ y: 10 * PX, blur: 15 * PX, color: tk.dark ? '#00000066' : '#0000000d' }), dropShadow({ y: 4 * PX, blur: 6 * PX, color: tk.dark ? '#00000044' : '#0000000a' })]}>
      <Rect id={id + '-bg'} width={width} height={h} radius={12 * PX} fill={tk.popover} stroke={{ color: tk.border, width: 1 * PX }} />
      {title ? (
        <>
          <Text id={id + '-title'} x={14 * PX} y={(40 - 14 * 1.25) / 2 * PX} font={fonts.sans} weight={500} size={14 * PX} color={tk.popoverFg}>{title}</Text>
          <Rect id={id + '-rule'} x={1 * PX} y={headH - 1 * PX} width={width - 2 * PX} height={1 * PX} fill={tk.border} />
        </>
      ) : null}
      {rows.map((r, i) => {
        const ry = headH + (12 + i * 28) * PX;
        return (
          <Layer id={`${id}-row${i}`} key={i}>
            <Ellipse id={`${id}-dot${i}`} x={14 * PX} y={ry + 6 * PX} width={8 * PX} height={8 * PX} fill={r.color} />
            <Text id={`${id}-lab${i}`} x={30 * PX} y={ry + (20 - 14 * 1.25) / 2 * PX} font={fonts.sans} size={14 * PX} color={tk.mutedFg}>{r.label}</Text>
            <Text id={`${id}-val${i}`} x={width - 14 * PX - 200 * PX} y={ry + (20 - 14 * 1.25) / 2 * PX} maxWidth={200 * PX} align="right" font={fonts.sans} weight={500} size={14 * PX} color={tk.popoverFg}>{r.value}</Text>
          </Layer>
        );
      })}
    </Layer>
  );
};

/** Natural width of a tooltip with these rows (so a panel never clips its text). */
export const tipWidth = (title: string | undefined, rows: TipRow[], size = 14 * PX) => {
  const w = Math.max(
    title ? sansWidth(title, size) + 28 * PX : 0,
    ...rows.map((r) => sansWidth(r.label, size) + sansWidth(r.value, size) + (14 + 8 + 8 + 24 + 14) * PX),
    160 * PX,
  );
  return Math.ceil(w);
};

/** Bklit's date ticker: a dark rounded-full pill with the date in it. Centred on x, top at y. */
export const Pill: React.FC<{ id: string; x: number; y: number; text: string; tk: BkTokens; fonts: Fonts; opacity?: number; scale?: number }> = ({
  id, x, y, text, tk, fonts, opacity = 1, scale = 1,
}) => {
  const size = 14 * PX;
  const w = sansWidth(text, size) + 32 * PX;
  const h = 32 * PX;
  return (
    <Layer id={id} x={x} y={y + h / 2} anchorX={w / 2} anchorY={h / 2} opacity={opacity} scale={scale}
      effects={[dropShadow({ y: 8 * PX, blur: 12 * PX, color: tk.dark ? '#00000055' : '#00000026' })]}>
      <Rect id={id + '-bg'} width={w} height={h} radius={h / 2} fill={tk.pill} />
      <Text id={id + '-t'} x={0} y={(h - size * 1.25) / 2} maxWidth={w} align="center" font={fonts.sans} weight={500} size={size} color={tk.pillFg}>{text}</Text>
    </Layer>
  );
};

/** Rack focus: blur what is not the subject. r is in px; under 1 the layer is left sharp (the engine drops it). */
export const Soft: React.FC<{ id: string; r: number; opacity?: number; children: React.ReactNode }> = ({ id, r, opacity = 1, children }) => (
  <Layer id={id} opacity={opacity} effects={r >= 1 ? [blur(r)] : []}>
    {children}
  </Layer>
);

/** The heading over a chart: a title and a muted line. */
export const Heading: React.FC<{ id: string; x: number; y: number; title: string; sub?: string; tk: BkTokens; fonts: Fonts; opacity?: number; size?: number }> = ({
  id, x, y, title, sub, tk, fonts, opacity = 1, size = 40,
}) => (
  <Layer id={id} x={x} y={y} opacity={opacity}>
    <Text id={id + '-t'} font={fonts.sans} weight={500} size={size} color={tk.fg}>{title}</Text>
    {sub ? <Text id={id + '-s'} y={size * 1.5} font={fonts.sans} size={size * 0.62} color={tk.mutedFg}>{sub}</Text> : null}
  </Layer>
);

/** Page background. */
export const Backdrop: React.FC<{ tk: BkTokens; W: number; H: number }> = ({ tk, W, H }) => <Rect id="bk-bg" width={W} height={H} fill={tk.bg} />;

export { mix };

// Candlestick chart, after Bklit UI's Candlestick Chart (MIT): OHLC candles in --chart-positive (emerald) and
// --chart-negative (red), a 1.5 px wick and a square-cornered body, dashed grid rows and columns, price labels on the
// left, dates under, and a tooltip with Open, High, Low, Close. Bklit fades each candle in from its wick centre,
// one after another.
//
// Shot: the camera starts tight on the first candles and rides the newest one as the series prints, a little ahead of
// it, following the price up and down. The candles speed through the quiet stretch and slow when the breakout starts,
// so the move gets the time. After the last candle it holds, pulls back a hair (anticipation) and pulls out to the
// whole chart with motion blur and overshoot, grid and labels snapping from soft to sharp. A tooltip opens on the
// last candle and slides to the biggest green one.
//
// Principles: staging, timing (fast through the quiet, slow through the breakout), anticipation and overshoot on the
// pull out, arcs (the camera follows smoothed price), follow-through (tooltip after the camera), depth of field.

import React from 'react';
import { z } from 'zod';
import { Layer, Path, Rect, Text } from '@kinetographdev/core';
import { Cam, H, W, clamp01, drift, easeOut, fmt, fmtSchema, hexA, lerp, niceScale, seg, stroke, useFonts, type NumFmt } from './lib.js';
import { PX, avg, backOut, bkModeSchema, bkPaletteSchema, moveCurve, shutterFor, soft, tokens } from './bklit.js';
import { Backdrop, BkTooltip, Heading, Pill, Soft, tipWidth } from './bklitParts.js';

export const CANDLE_FPS = 60;

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function makeCandles(n: number) {
  let s = 424242;
  const rnd = () => ((s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296);
  const out: { open: number; high: number; low: number; close: number }[] = [];
  let price = 100;
  const bo = Math.floor(n * 0.7);
  for (let k = 0; k < n; k++) {
    const open = price;
    const drift_ = k < bo ? (rnd() - 0.5) * 5.6 : 0.9 + rnd() * 2.6;
    const close = open + drift_ - (k < bo ? (price - 104) * 0.14 : 0);
    const wick = 1.2 + rnd() * 3.2;
    out.push({ open: +open.toFixed(2), close: +close.toFixed(2), high: +(Math.max(open, close) + wick * rnd() * 1.6).toFixed(2), low: +(Math.min(open, close) - wick * rnd() * 1.6).toFixed(2) });
    price = close;
  }
  return out;
}

export const candleSchema = z.object({
  data: z.array(z.object({ open: z.number(), high: z.number(), low: z.number(), close: z.number() }))
    .min(8).max(80).describe('The candles, oldest first. Open, high, low, close.'),
  startDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).describe('Date of the first candle, YYYY-MM-DD. Candles fall on weekdays.'),
  title: z.string().describe('Heading.'),
  subtitle: z.string().describe('Muted line under the heading.'),
  mode: bkModeSchema,
  palette: bkPaletteSchema,
  format: fmtSchema,
  printSeconds: z.number().min(1).max(14).describe('How long the candles take to print.'),
  holdSeconds: z.number().min(0).max(8).describe('How long the last frame holds.'),
  camera: z.object({
    tightZoom: z.number().min(1.2).max(4).describe('Zoom while riding the newest candle.'),
    wideZoom: z.number().min(0.7).max(1.3).describe('Zoom of the whole chart.'),
    lead: z.number().min(0).max(500).describe('Screen pixels the camera leads the newest candle by.'),
    motionBlur: z.number().min(0).max(1.5).describe('Strength of the motion blur on the fast moves; 0 turns it off.'),
    rackFocus: z.number().min(0).max(12).describe('Blur in pixels on the grid and labels while the shot is tight.'),
    drift: z.number().min(0).max(12).describe('Handheld drift in pixels on the holds.'),
  }).describe('Camera.'),
});
export type CandleProps = z.infer<typeof candleSchema>;

const fmt2: NumFmt = { prefix: '$', suffix: '', decimals: 2, group: ',' };

export const candleDefaults: CandleProps = {
  data: makeCandles(44),
  startDate: '2026-02-02',
  title: 'ACME',
  subtitle: 'Daily price, last 44 sessions',
  mode: 'light',
  palette: 'primary',
  format: fmt2,
  printSeconds: 4,
  holdSeconds: 1.6,
  camera: { tightZoom: 2.6, wideZoom: 1, lead: 300, motionBlur: 1, rackFocus: 4, drift: 3 },
};

const S = (s: number) => Math.round(s * CANDLE_FPS);

/** Start frame of each candle: quick through the quiet stretch, slower from the breakout (the first run of green). */
function schedule(p: CandleProps) {
  const n = p.data.length;
  const bo = Math.floor(n * 0.7);
  const wq = 1;
  const wb = 1.9;
  const total = bo * wq + (n - bo) * wb;
  const unit = S(p.printSeconds) / total;
  const start: number[] = [];
  let t = S(0.3);
  for (let k = 0; k < n; k++) {
    start[k] = Math.round(t);
    t += (k < bo ? wq : wb) * unit;
  }
  return { start, end: Math.round(t), bo };
}
const times = (p: CandleProps) => {
  const sc = schedule(p);
  const a0 = sc.end + S(0.5);
  const m0 = a0 + S(0.3);
  const m1 = m0 + S(1.7);
  const t0 = m1 + S(0.1);
  const g0 = t0 + S(0.5);
  const g1 = g0 + S(0.8);
  return { ...sc, a0, m0, m1, t0, g0, g1, tEnd: g1 + S(p.holdSeconds) };
};
export const candleDuration = (p: CandleProps) => times(p).tEnd;

const PX0 = 230;
const PX1 = 1750;
const PTOP = 310;
const PBASE = 900;

export const CandlestickChart: React.FC<{ f: number } & CandleProps> = ({ f, ...p }) => {
  const fonts = useFonts();
  const tk = tokens(p.mode, p.palette);
  const n = p.data.length;
  const T = times(p);
  const slot = (PX1 - PX0) / n;
  const bodyW = slot * 0.74;
  const lo = Math.min(...p.data.map((d) => d.low));
  const hi = Math.max(...p.data.map((d) => d.high));
  const sc = niceScale(lo - (hi - lo) * 0.04, hi + (hi - lo) * 0.04, 5);
  const yOf = (v: number) => PBASE - ((v - sc.min) / (sc.max - sc.min)) * (PBASE - PTOP);
  const xOf = (k: number) => PX0 + slot * (k + 0.5);
  const start = new Date(p.startDate + 'T00:00:00Z');
  const dateOf = (k: number) => {
    const d = new Date(start.getTime());
    let left = k;
    while (left > 0) {
      d.setUTCDate(d.getUTCDate() + 1);
      const wd = d.getUTCDay();
      if (wd !== 0 && wd !== 6) left--;
    }
    return d;
  };
  const label = (k: number) => `${MONTHS[dateOf(k).getUTCMonth()]} ${dateOf(k).getUTCDate()}`;

  // each candle's own progress: wick from the centre, body pops
  const born = (k: number) => seg(f, T.start[k], T.start[k] + S(0.24), easeOut);
  // newest candle position (fractional): where the printing is
  const frontAt = (ff: number) => {
    let k = 0;
    while (k < n - 1 && ff >= T.start[k + 1]) k++;
    const b = seg(ff, T.start[k], T.start[k] + S(0.24), easeOut);
    return k + b;
  };

  // ---- camera: ride the front, follow smoothed price
  const wide: [number, number, number] = [W / 2, H / 2, p.camera.wideZoom];
  const camAt = (ff: number): [number, number, number] => {
    const fr = Math.min(n - 1, frontAt(ff));
    const z0 = p.camera.tightZoom * (1 - 0.1 * clamp01(fr / (n - 1)));
    const lead = p.camera.lead * (1 - 0.8 * seg(ff, T.start[n - 1] - S(0.3), T.start[n - 1] + S(0.3), (t) => t * t * (3 - 2 * t)));
    const x = xOf(fr) + lead / z0;
    const price = (kk: number) => p.data[Math.max(0, Math.min(n - 1, Math.round(kk)))].close;
    const y = yOf(avg((kk) => price(kk), fr - 6, fr + 2, 9)) + 20;
    const a = seg(ff, T.a0, T.m0, (t) => t * t * (3 - 2 * t));
    const z = z0 * (1 + 0.05 * a);
    const w = moveCurve(seg(ff, T.m0, T.m1, (t) => t), 0, 0.055);
    return [lerp(x - 22 * a, wide[0], w), lerp(y, wide[1], w), Math.exp(lerp(Math.log(z), Math.log(wide[2]), w))];
  };
  const cam = camAt(f);
  const dr = drift(f, p.camera.drift * (f > T.m1 ? 1 : 0.3), 2.1);
  const shutter = shutterFor(camAt(Math.max(0, f - 1)), cam) * p.camera.motionBlur;
  const sharp = seg(f, T.m0 + S(0.2), T.m1 - S(0.35), easeOut);
  const gridBlur = soft(1 - sharp, p.camera.rackFocus);
  const reveal = seg(f, 0, S(0.4), easeOut);
  const headK = seg(f, T.m0 + S(0.3), T.m1 - S(0.2), easeOut);

  // ---- hover: opens on the last candle, slides to the biggest green body
  let big = 0;
  p.data.forEach((d, k) => { if (k >= schedule(p).bo && k < n - 4 && d.close - d.open > p.data[big].close - p.data[big].open) big = k; });
  const tOpen = seg(f, T.t0, T.t0 + S(0.3), easeOut);
  const glide = seg(f, T.g0, T.g1, easeOut);
  const hxk = lerp(n - 1, big, glide);
  const hk = Math.max(0, Math.min(n - 1, Math.round(hxk)));
  const hx = xOf(hxk);
  const d = p.data[hk];
  const rows = [
    { color: tk.label, label: 'Open', value: fmt(d.open, p.format) },
    { color: tk.label, label: 'High', value: fmt(d.high, p.format) },
    { color: tk.label, label: 'Low', value: fmt(d.low, p.format) },
    { color: d.close >= d.open ? tk.positive : tk.negative, label: 'Close', value: fmt(d.close, p.format) },
  ];
  const tw = tipWidth(label(hk), rows);
  const tipH = (40 + 24 + rows.length * 20 + (rows.length - 1) * 8) * PX;
  const pop = backOut(tOpen);
  const tipX = Math.min(hx - tw - 18 * PX, PX1 - tw);
  const tipY = Math.max(PTOP - 70, yOf(d.high) - tipH - 40);

  return (
    <Layer id="candle-root">
      <Backdrop tk={tk} W={W} H={H} />
      <Cam id="candle-cam" x={cam[0] + dr.x} y={cam[1] + dr.y} zoom={cam[2]} blur={shutter}>
        <Heading id="candle-head" x={PX0 - 60} y={96} title={p.title} sub={p.subtitle} tk={tk} fonts={fonts} opacity={headK} />

        {/* grid rows and columns, price labels, dates */}
        <Soft id="candle-soft" r={gridBlur} opacity={reveal}>
          {sc.ticks.map((t, i) => (
            <Layer id={`candle-row-${i}`} key={i}>
              <Path id={`candle-gl-${i}`} d={`M${PX0} ${yOf(t)}H${PX1}`} stroke={stroke(tk.grid, 2, { dash: [8, 8] })} />
              <Text id={`candle-yl-${i}`} x={PX0 - 24 - 140} y={yOf(t) - 15} maxWidth={140} align="right" font={fonts.sans} size={12 * PX} color={tk.label}>{fmt(t, { ...p.format, decimals: 0 })}</Text>
            </Layer>
          ))}
          {p.data.map((_, k) => (k % 6 === 3 ? (
            <Layer id={`candle-col-${k}`} key={k}>
              <Path id={`candle-vl-${k}`} d={`M${xOf(k)} ${PTOP}V${PBASE}`} stroke={stroke(tk.grid, 2, { dash: [8, 8] })} />
              <Text id={`candle-xl-${k}`} x={xOf(k) - 70} y={PBASE + 30} maxWidth={140} align="center" font={fonts.sans} size={12 * PX} color={tk.label}
                opacity={tOpen > 0 && Math.abs(k - hxk) < 1.6 ? 1 - tOpen : 1}>{label(k)}</Text>
            </Layer>
          ) : null))}
        </Soft>

        {/* candles */}
        {p.data.map((c, k) => {
          const b = born(k);
          if (b <= 0.001) return null;
          const up = c.close >= c.open;
          const col = up ? tk.positive : tk.negative;
          const yh = yOf(c.high);
          const yl = yOf(c.low);
          const mid = (yh + yl) / 2;
          const yo = yOf(c.open);
          const yc = yOf(c.close);
          const bt = Math.min(yo, yc);
          const bh = Math.max(2, Math.abs(yc - yo));
          const wk = easeOut(clamp01(b * 1.4));
          const bm = backOut(clamp01((b - 0.15) / 0.85), 1.4);
          const hov = tOpen > 0 && k === hk ? 1 : tOpen > 0 ? 0.75 : 1;
          const mc = (bt + bt + bh) / 2;
          return (
            <Layer id={`candle-${k}`} key={k} opacity={hov}>
              <Rect id={`candle-w-${k}`} x={xOf(k) - 1.5} y={mid - ((yl - yh) / 2) * wk} width={3} height={Math.max(1, (yl - yh) * wk)} fill={col} />
              <Rect id={`candle-b-${k}`} x={xOf(k) - bodyW / 2} y={mc - (bh * bm) / 2} width={bodyW} height={Math.max(1, bh * bm)} radius={2} fill={col} />
            </Layer>
          );
        })}

        {/* hover: crosshair, date pill, tooltip */}
        {tOpen > 0 ? (
          <Layer id="candle-hover" opacity={clamp01(tOpen * 1.6)}>
            <Rect id="candle-cross" x={hx - 1} y={PTOP - 30} width={2} height={PBASE - PTOP + 30} opacity={0.9}
              fill={{ type: 'linear', x0: 0, y0: PTOP - 30, x1: 0, y1: PBASE, stops: [{ offset: 0, color: hexA(tk.crosshair, 0) }, { offset: 0.12, color: hexA(tk.crosshair, 1) }, { offset: 0.9, color: hexA(tk.crosshair, 1) }, { offset: 1, color: hexA(tk.crosshair, 0) }] }} />
            <Pill id="candle-pill" x={hx} y={PBASE + 12} text={label(hk)} tk={tk} fonts={fonts} scale={0.85 + 0.15 * pop} />
            <BkTooltip id="candle-tt" x={tipX} y={tipY} title={label(hk)} rows={rows} tk={tk} fonts={fonts} width={tw}
              scale={0.9 + 0.1 * pop} pivot={[tw, tipH]} />
          </Layer>
        ) : null}
      </Cam>
    </Layer>
  );
};

// Shared parts of the chart components: themes, fonts, timing, number formatting, a camera, and the pieces every
// chart draws (a tooltip card, a hairline grid). Nothing here keeps state; every value is a function of the frame.

import React from 'react';
import { z } from 'zod';
import { Easing, interpolate } from 'remotion';
import { Layer, Path as Path_, Rect, Text, dropShadow } from '@kinetographdev/core';
import { loadFont as loadGeist } from '@remotion/google-fonts/Geist';
import { loadFont as loadGeistMono } from '@remotion/google-fonts/GeistMono';

export const W = 1920;
export const H = 1080;

// ---------------------------------------------------------------------------------------------------------------
// Timing

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
/** Slow in, slow out: the default for anything that travels. */
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
/** Fast start, long settle: for things that arrive. */
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);
export const linear = (t: number) => t;

/** 0..1 progress of frame f between frames a and b, eased and held outside. */
export const seg = (f: number, a: number, b: number, e: (t: number) => number = ease) =>
  interpolate(f, [a, b], [0, 1], { ...clamp, easing: e });
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
export const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

/** A monotone cubic through [frame, value] keys: a camera that glides through its marks without stopping or
 *  overshooting them. Flat at both ends (so it eases in and out of a hold). */
export function glide(f: number, k: [number, number][]): number {
  const n = k.length;
  if (f <= k[0][0]) return k[0][1];
  if (f >= k[n - 1][0]) return k[n - 1][1];
  const d = k.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const s0 = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const s1 = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return s0 * s1 <= 0 ? 0 : (2 * s0 * s1) / (s0 + s1);
  });
  let i = 1;
  while (f > k[i][0]) i++;
  const [x0, y0] = k[i - 1];
  const [x1, y1] = k[i];
  const h = x1 - x0;
  const t = (f - x0) / h;
  const t2 = t * t;
  const t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * h * d[i - 1] + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * h * d[i];
}

// ---------------------------------------------------------------------------------------------------------------
// Colour

export const hexA = (hex: string, a: number) => {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.replace(/./g, '$&$&') : h.slice(0, 6), 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${clamp01(a).toFixed(4)})`;
};

export interface Theme {
  bg: string;
  /** The card the chart sits on. */
  card: string;
  /** Primary type. */
  ink: string;
  /** Secondary type, axis labels. */
  muted: string;
  /** Hairlines, grid. */
  grid: string;
  /** Card border. */
  border: string;
  /** Fill of a tooltip. */
  tip: string;
  tipInk: string;
  shadow: string;
}

// Restrained, slightly warm neutrals; the accent carries all the colour.
